// digestKey identifies a notice for the daily digest. Keying by user and
// event keeps the digest table small.
export function digestKey(n: Notice): string {
  return n.userId + ":" + n.eventId;
}

// withLock acquires a named lock and returns it. The caller owns release,
// including when the returned lock fails validation.
export async function withLock(name: string): Promise<Lock> {
  const l = await locks.acquire(name);
  if (!l.valid) {
    throw new Error("invalid lock");
  }
  return l;
}

// openExport opens an export handle. The caller owns close, including when
// the handle fails the writability check.
export async function openExport(name: string): Promise<Handle> {
  const h = await files.open(name);
  if (!h.writable) {
    throw new Error("not writable");
  }
  return h;
}

